import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 25 Do the English speak English?","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 25 Do the English speak English?","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 24 It could be worse","link":"/life/english/new-concept/book-2/unit-01/lesson-024"},"next":{"text":"第二册：实践与进步 · Lesson 26 The best art critics","link":"/life/english/new-concept/book-2/unit-02/lesson-026"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 24 It could be worse","link":"/life/english/new-concept/book-2/unit-01/lesson-024"},"next":{"text":"第二册：实践与进步 · Lesson 26 The best art critics","link":"/life/english/new-concept/book-2/unit-02/lesson-026"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-025.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-025.md"}'),s={name:"life/english/new-concept/book-2/unit-02/lesson-025.md"};function i(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-25-do-the-english-speak-english" tabindex="-1">第二册：实践与进步 · Lesson 25 Do the English speak English? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-25-do-the-english-speak-english" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 25 Do the English speak English?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>同一种语言在不同地区仍有口音差异；旅客在车站听懂了单词，却没有马上明白路线。本课的语言观察是：间接问句保留疑问词 where，但用 the bus stopped 的陈述语序；不能保留直接问句的 did the bus stop。完成学习后，请转述一次问路过程，包含一个 where 间接问句和一次澄清。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>language</td><td>/ˈlæŋɡwɪdʒ/</td><td>n.</td><td>语言</td><td>learn a language</td></tr><tr><td>accent</td><td>/ˈæksənt/</td><td>n.</td><td>口音</td><td>a regional accent</td></tr><tr><td>understand</td><td>/ˌʌndəˈstænd/</td><td>v.</td><td>理解</td><td>understand a question</td></tr><tr><td>route</td><td>/ruːt/</td><td>n.</td><td>路线</td><td>plan a route</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>ask somebody a question — 问某人一个问题</li><li>in other words — 换句话说，用于重新解释</li></ul><h2 id="语法讲解-间接引语与视角转换" tabindex="-1">语法讲解：间接引语与视角转换 <a class="header-anchor" href="#语法讲解-间接引语与视角转换" aria-label="Permalink to &quot;语法讲解：间接引语与视角转换&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：间接问句保留疑问词 where，但用 the bus stopped 的陈述语序；不能保留直接问句的 did the bus stop。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I asked the driver where the bus stopped.</p></blockquote><p>我问司机这辆公共汽车在哪里停。</p><p>asked 带听者 the driver 和间接疑问从句；where 引导地点问题，从句不倒装。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I asked where did it stop 错误；从句应为 where it stopped。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照朗读直接问句 Where does it stop? 和转述 where it stopped，听语序与重音。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I asked the driver where the bus stopped. He repeated the name of the street. Once he showed me the map, I understood.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>转述一次问路过程，包含一个 where 间接问句和一次澄清。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：asked 带听者 the driver 和间接疑问从句；where 引导地点问题，从句不倒装。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：I asked where did it stop 错误；从句应为 where it stopped。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选语序：I asked where the bus stopped / where did the bus stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> where the bus stopped</p><p><strong>解析：</strong> 间接疑问句使用陈述语序。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>旅客看到什么后明白了？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The map.</p><p><strong>解析：</strong> 示范用 once 引出理解发生的条件。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 Where is the station? 接在 Could you tell me 后。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Could you tell me where the station is?</p><p><strong>解析：</strong> 从句中的主语 the station 在 is 之前。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语与视角转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-024">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-026">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",i]]);export{u as __pageData,b as default};
